-- Run after nothanks_schema.sql. The bytes are the same as public/no_thanks/bot-net.json (little-endian int16s).
insert into public.nothanks_net (id, scales, q) values (1, '{0.0000674581,0.000012284,0.0000353496,0.0000100711,0.000104657,0.0000122941,0.0000975372,0.0000140965,0.000049208,0.0000186608,0.0000351939,7.45628e-7}', decode('', 'base64'))
